FAILED = {"Failed", "Başarısız"}
SEV_ORDER = {"Düşük": 1, "Orta": 2, "Yüksek": 3, "Kritik": 4}


def _backfill_auto_defects() -> None:
    """Başarısız sonucu olan her koşum için bir 'auto' defect üretir (uygulama koduna bağımlı değil)."""
    conn = op.get_bind()
    cases = {r.id: r for r in conn.execute(sa.text("SELECT id, title, priority FROM test_cases"))}
    defects = sa.table(
        "defects",
        sa.column("title", sa.String), sa.column("severity", sa.String), sa.column("status", sa.String),
        sa.column("source", sa.String), sa.column("project_id", sa.Integer),
        sa.column("test_run_id", sa.Integer), sa.column("failed_details", sa.Text),
    )
    rows = []
    for run in conn.execute(sa.text("SELECT id, name, project_id, results FROM test_runs ORDER BY id")):
        try:
            results = json.loads(run.results or "[]")
        except (TypeError, ValueError):
            continue
        if not isinstance(results, list):
            continue
        details = []
        for idx, r in enumerate(x for x in results if isinstance(x, dict)
                                and (x.get("status") in FAILED or x.get("run_status") in FAILED)):
            cid = r.get("case_id") or r.get("test_case_id")
            tc = cases.get(cid)
            details.append({
                "case_id": cid,
                "title": (tc.title if tc else None) or r.get("test_case_title") or f"Test #{cid or idx + 1}",
                "error": r.get("actual_result") or r.get("error") or r.get("note"),
                "severity": (tc.priority if tc else None) or "Orta",
            })
        if not details:
            continue
        rows.append({
            "title": f"{run.name or 'İsimsiz Koşum'} — {len(details)} hatalı test",
            "severity": max((d["severity"] for d in details), key=lambda s: SEV_ORDER.get(s, 2)),
            "status": "Open", "source": "auto", "project_id": run.project_id, "test_run_id": run.id,
            "failed_details": json.dumps(details, ensure_ascii=False),
        })
    if rows:
        op.bulk_insert(defects, rows)


